    11  /**
    12   * Hook to handle redirection to the onboarding flow based on the user's onboarding status
    13   *
    14   * Warning: This hook should be used only once in the app
    15   */
    16  function useOnboardingFlowRouter() {
    17      const [isOnboardingCompleted, isOnboardingCompletedMetadata] = useOnyx(ONYXKEYS.NVP_ONBOARDING, {
    18          selector: hasCompletedGuidedSetupFlowSelector,
    19      });
    20      const [isHybridAppOnboardingCompleted, isHybridAppOnboardingCompletedMetadata] = useOnyx(ONYXKEYS.NVP_TRYNEWDOT, {
    21          selector: hasCompletedHybridAppOnboardingFlowSelector,
    22      });
    23
    24      useEffect(() => {
    25          if (isLoadingOnyxValue(isOnboardingCompletedMetadata, isHybridAppOnboardingCompletedMetadata)) {
    26              return;
    27          }
    28
    29          if (NativeModules.HybridAppModule) {
    30              // When user is transitioning from OldDot to NewDot, we usually show the explanation modal
    31              if (isHybridAppOnboardingCompleted === false) {
    32                  Navigation.navigate(ROUTES.EXPLANATION_MODAL_ROOT);
    33              }
    34
    35              // But if the hybrid app onboarding is completed, but NewDot onboarding is not completed, we start NewDot onboarding flow
    36              // This is a special case when user created an account from NewDot without finishing the onboarding flow and then logged in from OldDot
    37              if (isHybridAppOnboardingCompleted === true && isOnboardingCompleted === false) {
    38                  OnboardingFlow.startOnboardingFlow();
    39              }
    40          }
    41
    42          // If the user is not transitioning from OldDot to NewDot, we should start NewDot onboarding flow if it's not completed yet
    43          if (!NativeModules.HybridAppModule && isOnboardingCompleted === false) {
    44              OnboardingFlow.startOnboardingFlow();
    45          }
    46      }, [isOnboardingCompleted, isHybridAppOnboardingCompleted, isOnboardingCompletedMetadata, isHybridAppOnboardingCompletedMetadata]);
    47
    48      return {isOnboardingCompleted, isHybridAppOnboardingCompleted};
    49  }
