    14
    15  let selectedPurpose: string | undefined = '';
    16  Onyx.connect({
    17      key: ONYXKEYS.ONBOARDING_PURPOSE_SELECTED,
    18      callback: (value) => {
    19          selectedPurpose = value;
    20      },
    21  });
    22
    23  let onboardingInitialPath = '';
    24  const onboardingLastVisitedPathConnection = Onyx.connect({
    25      key: ONYXKEYS.ONBOARDING_LAST_VISITED_PATH,
    26      callback: (value) => {
    27          if (value === undefined) {
    28              return;
    29          }
    30          onboardingInitialPath = value;
    31          Onyx.disconnect(onboardingLastVisitedPathConnection);
    32      },
    33  });
    34
    35  let onboardingValues: Onboarding;
    36  Onyx.connect({
    37      key: ONYXKEYS.NVP_ONBOARDING,
    38      callback: (value) => {
    39          if (value === undefined) {
    40              return;
    41          }
    42          onboardingValues = value as Onboarding;
