    46  /**
    47   * Build the correct stack order for `onboardingModalNavigator`,
    48   * based on onboarding data (currently from the selected purpose).
    49   * The correct stack order will ensure that navigation and
    50   * the `goBack` navigatoin work properly.
    51   */
    52  function adaptOnboardingRouteState() {
    53      const currentRoute: NavigationPartialRoute | undefined = navigationRef.getCurrentRoute();
    54      if (!currentRoute || currentRoute?.name === SCREENS.ONBOARDING.PURPOSE) {
    55          return;
    56      }
    57
    58      const rootState = navigationRef.getRootState();
    59      const adaptedState = rootState;
    60      const lastRouteIndex = (adaptedState?.routes?.length ?? 0) - 1;
    61      const onBoardingModalNavigatorState = adaptedState?.routes.at(lastRouteIndex)?.state;
    62      if (!onBoardingModalNavigatorState || onBoardingModalNavigatorState?.routes?.length > 1 || lastRouteIndex === -1) {
    63          return;
    64      }
    65
    66      let adaptedOnboardingModalNavigatorState = {} as Readonly<PartialState<NavigationState>>;
    67      if (currentRoute?.name === SCREENS.ONBOARDING.ACCOUNTING && selectedPurpose === CONST.ONBOARDING_CHOICES.MANAGE_TEAM) {
    68          adaptedOnboardingModalNavigatorState = {
    69              index: 2,
    70              routes: [
    71                  {
    72                      name: SCREENS.ONBOARDING.PURPOSE,
    73                      params: currentRoute?.params,
    74                  },
    75                  {
    76                      name: SCREENS.ONBOARDING.EMPLOYEES,
    77                      params: currentRoute?.params,
    78                  },
    79                  {...currentRoute},
    80              ],
    81          } as Readonly<PartialState<NavigationState>>;
    82      } else {
    83          adaptedOnboardingModalNavigatorState = {
    84              index: 1,
    85              routes: [
    86                  {
    87                      name: SCREENS.ONBOARDING.PURPOSE,
    88                      params: currentRoute?.params,
    89                  },
    90                  {...currentRoute},
    91              ],
    92          } as Readonly<PartialState<NavigationState>>;
    93      }
    94
    95      const route = adaptedState.routes.at(lastRouteIndex);
    96
    97      if (route) {
    98          route.state = adaptedOnboardingModalNavigatorState;
    99      }
   100      navigationRef.resetRoot(adaptedState);
   101  }
