   106  function startOnboardingFlow() {
   107      const currentRoute = navigationRef.getCurrentRoute();
   108      const {adaptedState} = getAdaptedStateFromPath(getOnboardingInitialPath(), linkingConfig.config, false);
   109      const focusedRoute = findFocusedRoute(adaptedState as PartialState<NavigationState<RootStackParamList>>);
   110      if (focusedRoute?.name === currentRoute?.name) {
   111          return;
   112      }
   113      navigationRef.resetRoot(adaptedState);
   114  }
