   116  function getOnboardingInitialPath(): string {
   117      const state = getStateFromPath(onboardingInitialPath, linkingConfig.config);
   118      const isVsb = onboardingValues.signupQualifier === CONST.ONBOARDING_SIGNUP_QUALIFIERS.VSB;
   119
   120      if (isVsb) {
   121          Onyx.set(ONYXKEYS.ONBOARDING_PURPOSE_SELECTED, CONST.ONBOARDING_CHOICES.MANAGE_TEAM);
   122          return `/${ROUTES.ONBOARDING_EMPLOYEES.route}`;
   123      }
   124      const isIndividual = onboardingValues.signupQualifier === CONST.ONBOARDING_SIGNUP_QUALIFIERS.INDIVIDUAL;
   125      if (isIndividual) {
   126          Onyx.set(ONYXKEYS.ONBOARDING_CUSTOM_CHOICES, [CONST.ONBOARDING_CHOICES.PERSONAL_SPEND, CONST.ONBOARDING_CHOICES.EMPLOYER, CONST.ONBOARDING_CHOICES.CHAT_SPLIT]);
   127      }
   128      if (state?.routes?.at(-1)?.name !== NAVIGATORS.ONBOARDING_MODAL_NAVIGATOR) {
   129          return `/${ROUTES.ONBOARDING_ROOT.route}`;
   130      }
   131
   132      return onboardingInitialPath;
   133  }
   134
   135  function clearInitialPath() {
   136      onboardingInitialPath = '';
   137  }
   138
   139  /**
   140   * Onboarding flow: Go back to the previous page.
   141   * Since there is no `initialRoute` for `onBoardingModalNavigator`,
   142   * firstly, adjust the current onboarding modal navigator to establish the correct stack order.
   143   * Then, navigate to the previous onboarding page using the usual `goBack` function.
   144   */
   145  function goBack() {
   146      adaptOnboardingRouteState();
   147      Navigation.isNavigationReady().then(() => {
   148          Navigation.goBack();
   149      });
   150  }
   151
   152  export {getOnboardingInitialPath, startOnboardingFlow, clearInitialPath, goBack};

