     4  /**
     5   * Selector to get the value of hasCompletedGuidedSetupFlow from the Onyx store
     6   *
     7   * `undefined` means the value is not loaded yet
     8   * `true` means the user has completed the NewDot onboarding flow
     9   * `false` means the user has not completed the NewDot onboarding flow
    10   */
    11  function hasCompletedGuidedSetupFlowSelector(onboarding: OnyxValue<typeof ONYXKEYS.NVP_ONBOARDING>): boolean | undefined {
    12      // Onboarding is an array for old accounts and accounts created from OldDot
    13      if (Array.isArray(onboarding)) {
    14          return true;
    15      }
    16
    17      return onboarding?.hasCompletedGuidedSetupFlow;
    18  }
    19
    20  /**
    21   * Selector to get the value of completedHybridAppOnboarding from the Onyx store
    22   *
    23   * `undefined` means the value is not loaded yet
    24   * `true` means the user has completed the hybrid app onboarding flow
    25   * `false` means the user has not completed the hybrid app onboarding flow
    26   */
    27  function hasCompletedHybridAppOnboardingFlowSelector(tryNewDotData: OnyxValue<typeof ONYXKEYS.NVP_TRYNEWDOT>): boolean | undefined {
    28      let completedHybridAppOnboarding = tryNewDotData?.classicRedirect?.completedHybridAppOnboarding;
    29
    30      // Backend might return strings instead of booleans
    31      if (typeof completedHybridAppOnboarding === 'string') {
    32          completedHybridAppOnboarding = completedHybridAppOnboarding === 'true';
    33      }
    34
    35      return completedHybridAppOnboarding;
    36  }
    37
    38  export {hasCompletedGuidedSetupFlowSelector, hasCompletedHybridAppOnboardingFlowSelector};
